// Narrated video (at most 45 seconds) for a static model page. The page holds
// <section class="vt-video" id="video" data-video="<slug>"></section> and loads /videos/videos.js
// (generated by tools/video/build-embed.mjs) before this file. Language comes from the same cookie
// as the rest of the site ('vivatheca-lang'). Each video shows its review status, the model
// disclaimer (verbatim, from app/disclaimer-text.ts) and a link to /disclaimer, and lists the
// sources for every sentence it says.
(function () {
  const box = document.querySelector('[data-video]');
  const all = window.VT_VIDEOS || {};
  const v = box && all[box.dataset.video];
  if (!v) return;
  const slug = box.dataset.video;
  const cookie = (name) => (document.cookie.match('(?:^|; )' + name + '=([^;]*)') || [])[1];
  const lang = cookie('vivatheca-lang') === 'ja' ? 'ja' : 'en';
  const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const ruby = (s) => esc(s).replace(/\{([^{}|]+)\|([^{}]+)\}/g,
    '<ruby>$1<rp aria-hidden="true">(</rp><rt aria-hidden="true">$2</rt><rp aria-hidden="true">)</rp></ruby>');
  const plain = (s) => s.replace(/\{([^{}|]+)\|([^{}]+)\}/g, '$1');
  const T = {
    en: {
      heading: 'Watch: a short video about this model',
      meta: '{s} seconds · computer voice · subtitles',
      says: 'What the video says',
      review: '<b>Not yet clinically reviewed.</b> Educational model only. It shows typical anatomy or disease, not any real patient, and is simplified and may contain errors. Not for diagnosis, treatment planning, surgical guides or use in or on the body. <a href="/disclaimer">Full disclaimer</a>',
      voice: 'The voice is made by a computer (Kokoro-82M text to speech). The video shows the same 3D model as this page. It is made in the same way as the narrated video for the Vivatheca wisdom tooth model.',
      sources: 'Sources for the video',
      label: 'Narrated video: ',
      other: 'Watch in English',
      noVideo: 'Your browser cannot play this video.',
    },
    ja: {
      heading: 'この{模型|もけい}の{短|みじか}い{動画|どうが}',
      meta: '{s}{秒|びょう} · {機械|きかい}の{音声|おんせい} · {字幕|じまく}つき',
      says: '{動画|どうが}で{話|はな}していること',
      review: '<b>{臨床|りんしょう}レビュー{未実施|みじっし}。</b>{教育用|きょういくよう}の{模型|もけい}です。{特定|とくてい}の{患者|かんじゃ}ではなく{一般的|いっぱんてき}な{解剖|かいぼう}や{疾患|しっかん}を{示|しめ}したもので、{簡略化|かんりゃくか}されており{誤|あやま}りを{含|ふく}む{可能性|かのうせい}があります。{診断|しんだん}、{治療|ちりょう}{計画|けいかく}、{手術|しゅじゅつ}ガイド、{体内|たいない}・{体表|たいひょう}での{使用|しよう}には{用|もち}いないでください。<a href="/disclaimer">{免責|めんせき}{事項|じこう}の{全文|ぜんぶん}</a> <span lang="en"><b>Not yet clinically reviewed.</b> Educational model only. It shows typical anatomy or disease, not any real patient, and is simplified and may contain errors. Not for diagnosis, treatment planning, surgical guides or use in or on the body.</span>',
      voice: '{音声|おんせい}はコンピューターで{作|つく}ったものです（Kokoro-82M）。{日本語|にほんご}の{音声|おんせい}と{字幕|じまく}は、まだ{日本語|にほんご}を{話|はな}す{医療者|いりょうしゃ}の{確認|かくにん}を{受|う}けていません。',
      sources: '{動画|どうが}の{出典|しゅってん}',
      label: '{解説|かいせつ}{動画|どうが}：',
      other: 'Watch in English',
      noVideo: 'このブラウザでは{動画|どうが}を{再生|さいせい}できません。',
    },
  };
  const t = T[lang], L = v[lang];
  const files = (l) => ({ mp4: `/videos/${slug}/${slug}-${l}.mp4`, vtt: `/videos/${slug}/${slug}-${l}.vtt`, poster: `/videos/${slug}/poster-${l}.jpg` });
  const f = files(lang);
  const cite = (ns) => ns.map((n) => `<sup class="cite"><a href="#vsrc-${n}">${n}</a></sup>`).join('');
  const link = (s) => esc(s).replace(/(https?:\/\/[^\s]+)/g, (u) => `<a href="${u}">${u.replace(/^https?:\/\//, '')}</a>`);

  if (!document.getElementById('vt-video-css')) {
    const css = document.createElement('style');
    css.id = 'vt-video-css';
    css.textContent = `
.vt-video { padding: 18px 0; border-top: 1px solid var(--line, #cfe1e7); }
.vt-video h2 { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.vt-video-badge { display: inline-flex; align-items: center; gap: 6px; font-size: 13px; font-weight: 700; line-height: 1;
  padding: 6px 10px; border-radius: 999px; background: var(--heading, #00244d); color: var(--bg, #fff); }
.vt-video-badge::before { content: ''; width: 0; height: 0; border-left: 8px solid currentColor; border-top: 5px solid transparent; border-bottom: 5px solid transparent; }
.vt-video-meta { margin: 0 0 10px; color: var(--muted, #4d6378); font-size: 15px; }
.vt-video video { display: block; width: min(100%, 360px); aspect-ratio: 9 / 16; height: auto; max-height: 80vh; margin: 0 auto;
  background: #000; border-radius: 12px; }
.vt-video .vt-video-says { margin-top: 14px; }
.vt-video .vt-video-says p { margin: 0 0 6px; }
.vt-video .vt-video-review { font-size: 14px; color: var(--muted, #4d6378); }
.vt-video .vt-video-review b { color: var(--text, #06233f); }
html[lang="ja"] .vt-video .vt-video-review span[lang="en"] { display: none; }
.vt-video .vt-video-alt { font-size: 15px; }
.vt-video details { margin-top: 8px; }
.vt-video details summary { cursor: pointer; }
.vt-video details summary h3 { display: inline; font-size: 1rem; }
.vt-video ol { font-size: 14px; overflow-wrap: anywhere; }
/* Wide screens (2026-11-08): the upright video sits beside what it says, so the section fills the page column. */
@media (min-width: 1000px) {
  .vt-video { display: grid; grid-template-columns: 360px minmax(0,1fr); column-gap: clamp(2rem,4vw,3.5rem); align-items: start; }
  .vt-video > * { grid-column: 2; }
  .vt-video > h2, .vt-video > .vt-video-meta { grid-column: 1 / -1; }
  .vt-video > video { grid-column: 1; grid-row: 3 / span 20; width: 100%; margin: 0; }
  .vt-video .vt-video-says { margin-top: 0; }
}
@media (prefers-reduced-motion: no-preference) { .vt-video video { transition: box-shadow .2s; } }`;
    document.head.appendChild(css);
  }

  box.setAttribute('aria-labelledby', 'vt-video-h');
  if ((document.documentElement.lang || 'en').slice(0, 2) !== lang) box.setAttribute('lang', lang);
  box.innerHTML =
    `<h2 id="vt-video-h"><span class="vt-video-badge">${lang === 'ja' ? ruby('{動画|どうが}') : 'Video'}</span>${ruby(t.heading)}</h2>` +
    `<p class="vt-video-meta">${ruby(L.title)} · ${ruby(t.meta.replace('{s}', L.seconds))}</p>` +
    `<video controls playsinline preload="none" poster="${f.poster}" aria-label="${esc(plain(t.label + L.title))}">` +
      `<source src="${f.mp4}" type="video/mp4">` +
      `<track kind="captions" srclang="${lang}" label="${lang === 'ja' ? '日本語' : 'English'}" src="${f.vtt}">` +
      `<p>${ruby(t.noVideo)} <a href="${f.mp4}">MP4</a></p>` +
    `</video>` +
    `<div class="vt-video-says"><h3>${ruby(t.says)}</h3>` +
      `<p>${L.lines.map((l) => ruby(l.text) + cite(l.cite)).join(' ')}</p></div>` +
    (lang === 'ja' ? `<p class="vt-video-alt small"><a href="${files('en').mp4}" lang="en">${t.other}</a></p>` : '') +
    `<p class="vt-video-review">${lang === 'ja' ? t.review.replace(/\{([^{}|]+)\|([^{}]+)\}/g, (m, a, b) => ruby(`{${a}|${b}}`)) : t.review}</p>` +
    `<p class="small">${ruby(t.voice)}</p>` +
    `<details class="vt-video-refs"><summary><h3>${ruby(t.sources)}</h3></summary><ol>` +
      v.sources.map((s, i) => `<li id="vsrc-${i + 1}">${link(s)}</li>`).join('') +
    `</ol></details>`;
  // No Vietnamese video yet: say so in Vietnamese above the English video.
  if (cookie('vivatheca-lang') === 'vi') {
    box.insertAdjacentHTML('afterbegin', '<p class="vt-video-meta" lang="vi"><b>Video</b> · Video này hiện chỉ có tiếng Anh (có phụ đề tiếng Anh).</p>');
  }
})();
